const cfg = $('⚙️ Configuration ICP').first().json;
const demo = cfg.demo_mode !== false && cfg.demo_mode !== 'false';

if (!demo) {
  return $input.all();
}

const prospects = [
  { name: 'Camille Rousseau', role: 'Fondatrice', company: 'Studio Alto — SEO & contenu', agency_type: 'SEO / contenu', team_size: 14, client_count: 22, decision_maker: 'oui', recurring_reports: 'oui', linkedin_bio: 'On livre des rapports SEO mensuels a chaque client. Trop de temps en copier-coller Search Console.', recent_post: 'Le reporting client nous mange 6h par semaine.', website_snippet: 'Agence SEO Paris' },
  { name: 'Marc Duval', role: 'CEO', company: 'Pulse Social', agency_type: 'Social media', team_size: 18, client_count: 35, decision_maker: 'oui', recurring_reports: 'oui', linkedin_bio: 'Social ads + reporting client hebdo. Onboarding nouveau client = checklist Notion refaite a la main.', recent_post: '', website_snippet: '' },
  { name: 'Leila Benali', role: 'Directrice ops', company: 'Fullstack Com', agency_type: 'Full-service', team_size: 42, client_count: 48, decision_maker: 'oui', recurring_reports: 'oui', linkedin_bio: 'CRM HubSpot + Sheets + Slack — rien n est connecte. Rapports multi-canaux chaque lundi.', recent_post: 'Cherche a automatiser onboarding client.', website_snippet: '' },
  { name: 'Thomas Girard', role: 'Media Buyer', company: 'Ads Only FR', agency_type: 'SEA', team_size: 6, client_count: 12, decision_maker: 'non', recurring_reports: 'oui', linkedin_bio: 'Google Ads Meta Ads', recent_post: 'ROAS tips', website_snippet: '' },
  { name: 'Sophie Martin', role: 'Consultante solo', company: 'SM Conseil', agency_type: 'solopreneur', team_size: 1, client_count: 3, decision_maker: 'oui', recurring_reports: 'non', linkedin_bio: 'Freelance marketing', recent_post: '', website_snippet: '' }
];

return prospects.map(p => ({ json: { ...p, source: 'demo', niche: 'ops-agence' } }));

const cfg = $('⚙️ Configuration ICP').first().json;
const minScore = Number(cfg.min_score) || 55;
const pains = {
  reporting: {
    weight: Number(cfg.weight_reporting) || 45,
    signals: ['reporting', 'rapport client', 'rapport hebdo', 'rapport mensuel', 'looker', 'data studio', 'dashboard client', 'point client', 'compte rendu', 'synthese client', 'livrer des rapports', 'reporting client']
  },
  onboarding: {
    weight: Number(cfg.weight_onboarding) || 35,
    signals: ['onboarding', 'nouveau client', 'kick-off', 'kick off', 'checklist client', 'brief client', 'entree client', 'setup client', 'bienvenue client']
  },
  integrations: {
    weight: Number(cfg.weight_integrations) || 20,
    signals: ['copier-coller', 'copier coller', 'manuel', 'notion', 'crm', 'slack', 'sheets', 'zapier', 'make.com', 'make ', 'integre', 'connecter les outils', 'process interne']
  }
};

function norm(s) { return (s || '').toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, ''); }

const items = $input.all().map(i => i.json);
const results = [];

for (const p of items) {
  const blob = norm([
    p.company, p.company_description, p.role, p.name,
    p.linkedin_bio, p.recent_post, p.website_snippet, p.notes, p.agency_type
  ].filter(Boolean).join(' '));

  const clientCount = Number(p.client_count) || 0;
  const teamSize = Number(p.team_size) || 0;
  let score = 0;
  const matched = { reporting: [], onboarding: [], integrations: [] };
  const reasons = [];

  for (const [key, cfgPain] of Object.entries(pains)) {
    let hits = 0;
    for (const sig of cfgPain.signals) {
      const s = norm(sig);
      if (blob.includes(s)) {
        hits++;
        if (matched[key].length < 3) matched[key].push(sig);
      }
    }
    if (hits > 0) {
      const pts = Math.min(cfgPain.weight, hits * Math.ceil(cfgPain.weight / 2));
      score += pts;
      reasons.push(`${key}: ${matched[key].join(', ') || hits + ' signal(s)'}`);
    }
  }

  // Structure agence (pas secteur)
  if (teamSize >= 5 && teamSize <= 60) { score += 8; reasons.push('taille agence 5-60'); }
  if (clientCount >= 8) { score += 10; reasons.push('portefeuille clients >= 8'); }
  if (p.decision_maker === true || p.decision_maker === 'oui') { score += 7; reasons.push('decideur'); }
  if (p.recurring_reports === true || p.recurring_reports === 'oui') { score += 12; reasons.push('rapports recurrents confirmes'); }

  // Pas de penalite secteur — bonus si type agence generique
  const types = norm(p.agency_type || '');
  if (types && !types.includes('ecommerce') && !types.includes('solopreneur')) {
    score += 3;
  }

  score = Math.min(100, score);
  const primaryPain = ['reporting', 'onboarding', 'integrations']
    .sort((a, b) => (matched[b].length * pains[b].weight) - (matched[a].length * pains[a].weight))[0];
  const tier = score >= 75 ? 'A' : score >= minScore ? 'B' : 'C';
  const qualified = score >= minScore;

  let angle = '';
  if (matched.reporting.length) angle = `Reporting auto — ${p.company || p.name}`;
  else if (matched.onboarding.length) angle = `Onboarding auto — ${p.company || p.name}`;
  else if (matched.integrations.length) angle = `Outils connectes — ${p.company || p.name}`;
  else angle = `Ops agence — ${p.company || p.name}`;

  results.push({
    json: {
      ...p,
      icp_score: score,
      icp_tier: tier,
      icp_qualified: qualified ? 'oui' : 'non',
      icp_primary_pain: primaryPain,
      icp_matched_signals: matched,
      icp_reasons: reasons,
      icp_angle: angle,
      icp_cta: 'DEMO',
      icp_message_hook: qualified
        ? `Bonjour ${(p.name || '').split(' ')[0] || ''}, je vois que ${p.company || 'votre agence'} livre des rapports clients regulierement — j'ai un workflow qui compile + redige le commentaire chaque semaine. Je vous envoie un Loom de 2 min si vous tapez DEMO ?`
        : '',
      scored_at: new Date().toISOString()
    }
  });
}

return results.sort((a, b) => b.json.icp_score - a.json.icp_score);

const all = $('Scorer par douleur').all().map(i => i.json);
const qualified = all.filter(x => x.icp_qualified === 'oui');
const a = qualified.filter(x => x.icp_tier === 'A');
return [{ json: {
  total: all.length,
  qualified: qualified.length,
  tier_a: a.length,
  top: qualified.slice(0, 5).map(x => ({ name: x.name, company: x.company, score: x.icp_score, pain: x.icp_primary_pain, angle: x.icp_angle })),
  niche: $('⚙️ Configuration ICP').first().json.niche_label
}}];
